package com.mirigangneung.route.controller;import com.mirigangneung.route.dto.*;import com.mirigangneung.route.service.RouteService;import jakarta.validation.Valid;import org.springframework.web.bind.annotation.*;@RestController@RequestMapping("/api/v1/routes")public class RouteController{private final RouteService s;public RouteController(RouteService x){s=x;}@PostMapping("/walking")public WalkingRouteResponse walking(@Valid@RequestBody WalkingRouteRequest r){return s.walking(r);}}
